// Standardised SVG geometry and stroke; icons remain decorative next to visible labels.
export const icon=(name,size=18)=>{
  const key=Object.hasOwn(paths,name)?name:'info';
  const px=Number.isFinite(Number(size))?Math.max(12,Math.min(32,Math.round(Number(size)))):18;
  return `<svg class="fa-icon fa-icon-${key}" width="${px}" height="${px}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="var(--icon-stroke,1.8)" stroke-linecap="round" stroke-linejoin="round" focusable="false" aria-hidden="true">${paths[key]}</svg>`;
};
export const badge=(club,size='md')=>{
  if(!club)return '';
  const {primary,secondary,ink}=clubPalette(club);
  const scale=['xs','sm','md','lg','xl'].includes(size)?size:'md';
  const initials=String(club.short||club.name||'?').slice(0,2);
  return `<span class="crest crest-${scale}" style="--crest:${primary};--crest-dark:${secondary};--crest-ink:${ink}" role="img" aria-label="${esc(club.name)}"><span aria-hidden="true">${esc(initials)}</span></span>`;
};
export const avatar=(player,size='md')=>{
  if(!player)return '';
  const scale=['sm','md','xl'].includes(size)?size:'md';
  return `<span class="avatar avatar-${scale}" role="img" aria-label="${esc(player.name)}"><span aria-hidden="true">${esc(monogram(player.name))}</span></span>`;
};

