const tableAria=(label,lang)=>`aria-label="${esc(lang==='en'?label.en:label.it)}"`;

// QOL05.06 — a single safe native select builder. Preserve HTML select semantics:
// keyboard arrows, type-to-select, OS mobile picker, label association and onchange.
// The option values are stable internal keys, never translated to display labels.
export const selectControl=({id,value,options,className='',ariaLabel='',disabled=false,attrs=''})=>
  `<select id="${esc(id)}" class="select-control${className?' '+esc(className):''}"${ariaLabel?` aria-label="${esc(ariaLabel)}"`:''}${disabled?' disabled':''}${attrs?' '+attrs:''}>${options.map(({value:optionValue,label,disabled:optionDisabled=false})=>`<option value="${esc(optionValue)}"${String(value)===String(optionValue)?' selected':''}${optionDisabled?' disabled':''}>${esc(label)}</option>`).join('')}</select>`;
// QOL05.07 — native controls for future forms, and the actual market-watch switch.
// The input is wrapped in its label: clicking any part of the label activates it.
// A switch remains a checkbox (Space toggles it), with role="switch" for assistive tech.
export const selectionControl=({type='checkbox',id,label,checked=false,disabled=false,name='',value='on',description='',attrs=''})=>{
  if(!['checkbox','radio','switch'].includes(type))throw new TypeError('Unsupported selection control');
  if(!id||!label||type==='radio'&&!name)throw new TypeError('Selection control needs an id, label and radio group name');
  const inputType=type==='switch'?'checkbox':type;
  return `<label class="selection-control selection-${type}${disabled?' is-disabled':''}"><input class="selection-native" id="${esc(id)}" type="${inputType}"${type==='switch'?' role="switch"':''}${name?` name="${esc(name)}"`:''} value="${esc(value)}"${checked?' checked':''}${disabled?' disabled':''}${attrs?' '+attrs:''}><span class="selection-indicator" aria-hidden="true"></span><span class="selection-copy"><span class="selection-label">${esc(label)}</span>${description?`<small>${esc(description)}</small>`:''}</span></label>`;
};
// Native range: numeric value is announced by the browser; output is for sighted users.
export const sliderControl=({id,label,min=0,max=100,step=1,value=min,disabled=false,unit=''})=>{
  if(!id||!label||![min,max,step,value].every(Number.isFinite)||min>=max||step<=0)throw new TypeError('Invalid slider configuration');
  const bounded=Math.max(min,Math.min(max,value));
  const selected=Number(Math.max(min,Math.min(max,min+Math.round((bounded-min)/step)*step)).toFixed(8));
  const position=(selected-min)/(max-min)*100;
  return `<div class="selection-range${disabled?' is-disabled':''}"><label for="${esc(id)}">${esc(label)}</label><div class="selection-range-track"><input class="selection-slider" id="${esc(id)}" type="range" min="${min}" max="${max}" step="${step}" value="${selected}" data-unit="${esc(unit)}" style="--range-position:${position}%"${disabled?' disabled':''}><output for="${esc(id)}">${selected}${esc(unit)}</output></div></div>`;
};
// Exclusive choices use native radio inputs; the internal keys stay in Italian.
const segmentedChoice=(name,value,selected,action,label=value)=>`<label class="selection-segment${selected?' seg-active':''}"><input class="selection-native" type="radio" name="${esc(name)}" value="${esc(value)}" data-action="${esc(action)}" data-value="${esc(value)}"${selected?' checked':''}><span>${esc(label)}</span></label>`;
const languagePicker=(ui,context)=>{
  const en=ui.language==='en',label=en?'Language':'Lingua',open=ui.languageMenu===context;
  const current=en?{code:'EN',name:'English'}:{code:'IT',name:'Italiano'};
  const popupId=`language-list-${context}`,buttonId=`language-combobox-${context}`;
  const options=[{value:'it',code:'IT',label:'Italiano'},{value:'en',code:'EN',label:'English'}];
  return `<div class="language-picker language-picker-${context}" data-language-picker="${context}">
    <button type="button" class="language-combobox" id="${buttonId}" role="combobox" aria-label="${label}: ${current.name}" aria-haspopup="listbox" aria-expanded="${open}" aria-controls="${popupId}" data-action="language-toggle" data-value="${context}">
      <span class="language-icon" aria-hidden="true">${icon('flag',15)}</span>
      <span class="language-current" id="${buttonId}-value"><b>${current.code}</b><span>${current.name}</span></span>
      <span class="language-chevron" aria-hidden="true">${icon('down',14)}</span>
    </button>
    ${open?`<div class="language-listbox" id="${popupId}" role="listbox" aria-label="${label}" data-language-listbox="${context}">
      ${options.map(option=>`<button type="button" class="language-option${ui.language===option.value?' is-selected':''}" role="option" aria-selected="${ui.language===option.value}" data-action="language-option" data-value="${option.value}" data-context="${context}" tabindex="-1"><span class="language-option-code">${option.code}</span><span>${option.label}</span>${ui.language===option.value?icon('check',14):''}</button>`).join('')}
    </div>`:''}
  </div>`;
};
// QOL05.05 — reusable text field / search shell. Visuals are defined in styles.css.
// Every clear action is an explicit user gesture; never mutate filters on input render.
const clearableField=({id,label,value='',placeholder='',maxLength,search=false,helpId='',invalid=false,errorId=''})=>{
  const safeId=esc(id), safeLabel=esc(label), safeValue=esc(value);
  const attributes=[`id="${safeId}"`,`value="${safeValue}"`,`aria-label="${safeLabel}"`,`autocomplete="off"`,`placeholder="${esc(placeholder)}"`];
  if(maxLength)attributes.push(`maxlength="${Number(maxLength)}"`);
  const describedBy=[helpId,errorId].filter(Boolean).join(' ');if(describedBy)attributes.push(`aria-describedby="${esc(describedBy)}"`);if(invalid)attributes.push('aria-invalid="true"');
  const field=`<input class="form-control ${search?'search-input':'text-field'}" type="${search?'search':'text'}" ${attributes.join(' ')} />`;
  return `<div class="field-shell ${search?'search-field':'text-control'}" data-has-value="${String(value).length?'true':'false'}">${search?icon('search',18):''}${field}<button type="button" class="field-clear" data-action="clear-field" data-target="${safeId}" aria-label="${esc(label==='Cerca un calciatore'?'Cancella ricerca calciatori':label==='Search players'?'Clear player search':label==='Cerca calciatore o club'?'Cancella ricerca mercato':label==='Search players or clubs'?'Clear market search':label==='Nome della carriera'?'Cancella nome carriera':label==='Career name'?'Clear career name':label==='Manager name'?'Clear manager name':'Cancella nome allenatore')}" title="${esc(label==='Manager name'||label==='Career name'||label.startsWith('Search')?'Clear':'Cancella')}">${icon('close',15)}</button></div>`;
};
