function playerModal(w,p,ui){const lang=ui.language,pt=rosterText(lang),mine=p.clubId===w.clubId,team=clubById(w,p.clubId),fee=Math.round(p.value*1.1/50000)*50000;
 const report=scoutingEnabled(w)?scoutingEstimate(w,p.globalId??`${w.countryId}:${p.id}`):null;const range=v=>v?`${v.min}–${v.max}`:'—';
 const own=mine?clubPlayers(w,w.clubId):[];
 const other=own.find(x=>x.id===ui.comparePlayerId&&x.id!==p.id);
 const selector=mine?`<section class="ply01-compare-picker"><label for="ply01-compare-player">${lang==='en'?'Compare with':'Confronta con'}</label>${selectControl({id:'ply01-compare-player',value:other?String(other.id):'none',options:[{value:'none',label:lang==='en'?'Choose a teammate':'Scegli un compagno'},...own.filter(x=>x.id!==p.id).map(x=>({value:String(x.id),label:`${x.name} · ${x.position}`}))]})}</section>${other?renderPlayerComparison(p,other,{lang,seed:w.seed,countryId:w.countryId,attributes:['ballControl','shortPassing','finishing','tackling','marking','vision','decisions','teamwork','pace','stamina','strength','reflexes']}):''}`:'';
 const scoutAttributes=!mine&&scoutingEnabled(w)?`<section class="ply01-scout-estimate" aria-label="${lang==='en'?'Scout knowledge':'Conoscenza osservatori'}"><h3>${lang==='en'?'Scouting attribute estimates':'Stime attributi degli osservatori'}</h3>${report?.attributes?`<div class="ply01-scout-intervals">${Object.entries(report.attributes).map(([key,v])=>{const a=ATTRIBUTE_DEFINITIONS.find(d=>d.key===key);return a&&v?`<div><span>${esc(a.label[lang==='en'?'en':'it'])}</span><strong>${range(v)}</strong></div>`:'';}).join('')}</div>`:`<p>${lang==='en'?'Detailed estimates are not available. Assign scouting coverage and build a report.':'Le stime dettagliate non sono disponibili. Assegna osservatori e sviluppa un rapporto.'}</p>`}</section>`:'';
 return `<div class="modal-player-top"><div class="modal-person">${avatar(p,'xl')}<div><span class="eyebrow">${pt.profile}</span><h2>${esc(p.name)}</h2><p>${esc(p.nationality)} · ${p.age} ${lang==='en'?'years':'anni'} · ${lang==='en'?'Foot':'Piede'} ${esc(p.foot.toLowerCase())}</p><span class="modal-club">${badge(team,'xs')} ${esc(team.name)}</span></div></div><div class="modal-ovr">${scoutingEnabled(w)&&!mine?range(report?.overall):rating(p.ovr)}<span>${lang==='en'?'OVERALL<br>RATING':'VALUTAZIONE<br>GENERALE'}</span></div></div><section class="roster-profile-overview" aria-label="${pt.overview}"><div class="profile-data"><div><span>${lang==='en'?'POSITION':'RUOLO'}</span><strong>${esc(POSITION_LABELS[p.position])}</strong></div><div><span>${lang==='en'?'POTENTIAL':'POTENZIALE'}</span><strong>${scoutingEnabled(w)&&!mine?range(report?.potential):p.potential}</strong></div><div><span>${lang==='en'?'MARKET VALUE':'VALORE DI MERCATO'}</span><strong>${scoutingEnabled(w)&&!mine?(report?.valueEUR?`${displayCareerMoney(report.valueEUR.min,{countryId:w.countryId,lang})}–${displayCareerMoney(report.valueEUR.max,{countryId:w.countryId,lang})}`:'—'):displayCareerMoney(p.value,{countryId:w.countryId,lang})}</strong></div><div><span>${lang==='en'?'WAGE / WEEK':'INGAGGIO / SETTIMANA'}</span><strong>${displayCareerMoney(p.wage,{countryId:w.countryId,lang})}</strong></div><div><span>${lang==='en'?'CONTRACT':'CONTRATTO'}</span><strong>${p.contract} ${lang==='en'?(p.contract===1?'year':'years'):(p.contract===1?'anno':'anni')}</strong></div><div><span>${lang==='en'?'AVAILABILITY':'DISPONIBILITÀ'}</span><strong>${p.injury?`${p.injury} ${pt.days}`:pt.fit}</strong></div></div><div class="profile-stat-strip"><div><b>${p.apps}</b><span>${lang==='en'?'APPS':'PRESENZE'}</span></div>${p.minutesPlayed!==undefined?`<div><b>${Math.round(p.minutesPlayed)}</b><span>${lang==='en'?'MINUTES':'MINUTI'}</span></div>`:''}<div><b>${p.goals}</b><span>${lang==='en'?'GOALS':'GOL'}</span></div><div><b>${p.assists}</b><span>ASSIST</span></div><div><b>${p.fitness}%</b><span>${lang==='en'?'FITNESS':'FORMA FISICA'}</span></div></div><div class="roster-profile-indicators" role="group" aria-label="${pt.condition}"><span>${pt.fitness}: <strong>${Number.isFinite(Number(p.fitness))?Math.round(Number(p.fitness)):0}%</strong></span><span>${pt.morale}: <strong>${Number.isFinite(Number(p.morale))?Math.round(Number(p.morale)):0}/100</strong></span><span>${p.injury?`${pt.recovery}: ${esc(p.injury)} ${pt.days}`:pt.fit}</span><span>${lang==='en'?'Contract':'Contratto'}: <strong>${p.contract} ${lang==='en'?'years':'anni'}</strong></span></div></section><div class="modal-actions">${actionButton(`${icon('star',17)} ${w.watchlist.includes(p.id)?(lang==='en'?'Remove from watchlist':'Rimuovi osservato'):(lang==='en'?'Watch player':'Segui calciatore')}`,'watch','btn btn-outline',`data-id="${p.id}"`)}${marketEnabled(w)?actionButton(mine?(lang==='en'?'Negotiate sale':'Tratta cessione'):(lang==='en'?'Negotiate':'Avvia trattativa'),'market-offer-player','btn btn-primary',`data-id="${w.countryId}:${p.id}"`):(mine?actionButton(`Cedi · ${displayCareerMoney(p.value*.82,{countryId:w.countryId,lang})}`,'sell','btn btn-danger',`data-id="${p.id}"`):actionButton(`Acquista · ${displayCareerMoney(fee,{countryId:w.countryId,lang})} ${icon('arrow',17)}`,'buy','btn btn-primary',`data-id="${p.id}"`))}</div>${personalityEnabled(w)?`<section class="ply02-profile" aria-label="${lang==='en'?'Personality overview':'Panoramica personalità'}"><h3>${lang==='en'?'Personality and relationships':'Personalità e relazioni'}</h3>${(()=>{const v=personalityPlayerView(w,p,{lang,report});return `<div class="ply02-facts">${v.owned?`<div><span>${lang==='en'?'Morale':'Morale'}</span><strong>${Math.round(v.morale)}/100</strong></div><div><span>${lang==='en'?'Coach relationship':'Rapporto allenatore'}</span><strong>${Math.round(v.coachRelationship)}/100</strong></div>`:''}</div><div class="ply02-traits">${v.traits.map(t=>`<div><span>${esc(t.label)}</span><strong>${t.visibility==='hidden'?'—':t.visibility==='estimated'?`${t.range[0]}–${t.range[1]}`:esc(t.description||'—')}</strong></div>`).join('')}</div>${v.owned&&v.history.length?`<details><summary>${lang==='en'?'Recent changes':'Variazioni recenti'}</summary>${v.history.map(x=>`<p>${esc(x.type)}: ${x.delta>0?'+':''}${x.delta} (${esc(x.drivers.join(', '))})</p>`).join('')}</details>`:''}`;})()}</section>`:''}${mine?`<details class="roster-profile-section" open><summary>${pt.attributes}</summary><div class="ply01-player-details">${renderPlayerProfile(p,{lang,seed:w.seed,countryId:w.countryId})}${selector}</div></details>`:scoutAttributes}${!scoutingEnabled(w)&&mine?playerProjection(w,p,lang):''}`;
}
function advancedMatchReport(w,m,lang='it'){
 const a=m.result?.advancedV1;if(!a)return '';
 const safe=word=>esc(String(word??''));
 const label={goal:'Gol',shot:'Tiro',recovery:'Recupero',foul:'Fallo',pass:'Passaggio'};
 const events=a.events??[];
 const subs=a.matchday;
 const supplemental=subs?`<section class="sim04-report" aria-label="SIM04"><h3>Cambi / Substitutions</h3><ul>${subs.changes.map(c=>`<li>${c.minute}′ · ${esc(w.teams.find(t=>t.id===c.teamId)?.name||String(c.teamId))}: ${esc(historicPlayerName(w,c.out))} → ${esc(historicPlayerName(w,c.in))} (${c.reason})</li>`).join('')||'<li>—</li>'}</ul><details><summary>Minuti effettivi / Actual minutes</summary><div class="fa-addon-scroll"><table class="fa-addon-table"><thead><tr><th>Club</th><th>Player / Giocatore</th><th>Minuti / Minutes</th></tr></thead><tbody>${subs.minutes.flatMap(team=>team.players.filter(p=>p.seconds>0).map(p=>`<tr><td>${esc(w.teams.find(t=>t.id===team.teamId)?.name||String(team.teamId))}</td><td>${esc(historicPlayerName(w,p.playerId))}</td><td>${Math.round(p.minutes)}</td></tr>`)).join('')}</tbody></table></div></details></section>`:'';
 return `<div class="fa-addon-match-events"><h3>Eventi del motore avanzato</h3><p class="fa-addon-hint">Le azioni registrate determinano il risultato ufficiale della partita.</p><details><summary>Apri cronologia (${events.length} eventi selezionati)</summary><div class="fa-addon-scroll"><table class="fa-addon-table"><thead><tr><th>Minuto</th><th>Squadra</th><th>Azione</th><th>Giocatore</th></tr></thead><tbody>${events.map(e=>`<tr><td>${Math.floor(e.second/60)+1}'</td><td>${safe(e.side==='home'?w.teams.find(t=>t.id===m.home)?.short:w.teams.find(t=>t.id===m.away)?.short)}</td><td>${label[e.type]??safe(e.type)}</td><td>${safe(w.players.find(p=>p.id===e.playerId)?.name??'—')}</td></tr>`).join('')}</tbody></table></div></details>${a.injuries.length?`<h3>Infortuni</h3>${a.injuries.map(x=>`<p>${safe(w.players.find(p=>p.id===x.playerId)?.name)} · ${safe(x.kind)} · ${x.durationDays} giorni</p>`).join('')}`:''}${a.tacticalChanges?.length?`<section class="sim02-report" aria-label="SIM02"><h3>SIM02 · Tactical changes / Cambi tattici</h3><ol>${a.tacticalChanges.map(ch=>`<li>${ch.minute}′ · ${safe(ch.presetId)}</li>`).join('')}</ol></section>`:''}${a.coachPreparation?.length?`<section class="sim05-report" aria-label="SIM05"><h3>${lang==='en'?'AI managers':'Allenatori AI'} · SIM05</h3><p>${a.coachPreparation.map(p=>`${safe(w.teams.find(t=>t.id===p.teamId)?.name??'')} · ${safe(p.formation)} · ${safe(p.style)}`).join(' · ')}</p>${a.coachDecisions?.length?`<ol>${a.coachDecisions.map(d=>`<li>${d.minute}′ · ${safe(w.teams.find(t=>t.id===d.teamId)?.name??'')} · ${safe(d.reason)}</li>`).join('')}</ol>`:''}</section>`:''}${supplemental}</div>`;
}
function matchModal(w,m,lang='it'){
 const h=clubById(w,m.home),a=clubById(w,m.away),r=m.result;
 const tr=(it,en)=>lang==='en'?en:it;
 if(!r)return `<p class="empty-state">${tr('Partita non ancora disputata.','Match not yet played.')}</p>`;
 const numeric=v=>Number.isFinite(Number(v))?Number(v):0;
 const pct=v=>Math.min(100,Math.max(0,Math.round(numeric(v))));
 const row=(label,left,right,percent)=>`<div class="matchstat"><strong>${esc(left)}</strong><div><span>${esc(label)}</span><div class="stat-bars"><i style="width:${pct(percent)}%"></i><b style="width:${100-pct(percent)}%"></b></div></div><strong>${esc(right)}</strong></div>`;
 const shots=numeric(r.shotsHome)+numeric(r.shotsAway),xgs=numeric(r.xgHome)+numeric(r.xgAway);
 return `<div class="match-center-mode is-official" role="note"><strong>${tr('PARTITA UFFICIALE · RISULTATO FINALE','OFFICIAL MATCH · FINAL RESULT')}</strong><p>${tr('Questo è il risultato registrato della giornata di carriera.','This is the recorded result of the career matchday.')}</p></div>
  <div class="match-report-head"><div>${badge(h,'lg')}<b>${esc(h?.name||'—')}</b></div><div class="match-report-center"><span>${esc(w.competition||'Lega Aurora').toUpperCase()} · ${tr('GIORNATA','MATCHDAY')} ${esc(String(m.id).split('-')[1]||'—')}</span><small class="match-report-schedule">${formatCareerDateTime(m.date,m.kickoff,lang)}</small><strong>${r.homeGoals} <i>:</i> ${r.awayGoals}</strong><small>${tr('FINALE','FULL TIME')}</small></div><div>${badge(a,'lg')}<b>${esc(a?.name||'—')}</b></div></div>
  <div class="match-report-body"><h3>${tr('Statistiche','Match statistics')}</h3>
   ${row(tr('Possesso','Possession'),numeric(r.possessionHome)+'%',(100-numeric(r.possessionHome))+'%',r.possessionHome)}
   ${row(tr('Tiri totali','Total shots'),numeric(r.shotsHome),numeric(r.shotsAway),shots?numeric(r.shotsHome)/shots*100:50)}
   ${row('Expected goals',numeric(r.xgHome).toFixed(2),numeric(r.xgAway).toFixed(2),xgs?numeric(r.xgHome)/xgs*100:50)}
   <h3>${tr('Marcatori','Goalscorers')}</h3>
   ${(r.goals??[]).length?r.goals.map(g=>`<div class="goal-entry"><b>${g.minute}'</b>${icon('football',15)}<span>${esc(historicPlayerName(w,g.scorerId))}</span>${tag(g.side==='home'?h.short:a.short,g.side==='home'?'blue':'muted')}</div>`).join(''):`<div class="no-goals">${tr('Nessun gol segnato.','No goals scored.')}</div>`}
  </div>${officialMatchTimeline(w,m,lang)}${advancedMatchReport(w,m,lang)}${renderCareerStatisticsMatch(w,m,lang)}`;
}
function pickerModal(w,ui){const index=ui.modal.index,slot=FORMATIONS[w.formation][index],list=clubPlayers(w,w.clubId).filter(p=>!p.injury&&(!w.advancedV1?.enabled||!p.medicalV1||medicalAvailability(p.medicalV1).canStart)).sort((a,b)=>(b.position===slot.p?100:0)+b.ovr-((a.position===slot.p?100:0)+a.ovr));return `<p class="modal-explainer">Scegli il calciatore per il ruolo <b>${esc(POSITION_LABELS[slot.p])}</b>. Un giocatore già schierato verrà scambiato di posizione.</p><div class="picker-list">${list.map(p=>`<button data-action="assign" data-id="${p.id}" data-index="${index}" class="picker-player">${avatar(p,'sm')}<span><b>${esc(p.name)}</b><small>${p.position} · ${p.age} anni ${w.lineup.includes(p.id)?'· Titolare':''}</small></span>${rating(p.ovr)}${p.position===slot.p?tag('Naturale','green'):''}${icon('chevron',17)}</button>`).join('')}</div>${actionButton(`${icon('minus',16)} Lascia vuoto`,'clear-slot','btn btn-outline','data-index="'+index+'"')}`;}
function modalContent(w,ui){const m=ui.modal;let title='',inner='',wide=false;
 if(m.type==='player'){const p=playerById(w,m.id);if(!p)return '';title=ui.language==='en'?'Player profile':'Profilo calciatore';inner=playerModal(w,p,ui);wide=true;}
 else if(m.type==='market-offer'){title=ui.language==='en'?'Transfer offer':'Offerta di trasferimento';inner=marketOfferModal(w,ui);wide=true;}
 else if(m.type==='market-deal'){title=ui.language==='en'?'Negotiation dossier':'Dossier trattativa';inner=marketDealModal(w,ui);wide=true;}
 else if(m.type==='match'){const game=findMatch(w,m.id);if(!game)return '';title=ui.language==='en'?'Match report':'Resoconto partita';inner=matchModal(w,game,ui.language);wide=true;}
 else if(m.type==='sim04-halftime'){
   const half=m.preview;if(!half||!substitutionsEnabled(w)||m.round!==w.round||half.matchId!==expectedNextMatch(w)?.id)return '';
   title=ui.language==='en'?'Half-time: choose your changes':'Intervallo: decidi i cambi';wide=true;
   inner=`<div class="sim04-halftime-score" role="status"><strong>45′ · ${half.homeGoals} – ${half.awayGoals}</strong><p>${ui.language==='en'?'The first half is a read-only, seed-verified preview. Decide a substitution now; it will be executed before the second half.':'Il primo tempo è un’anteprima verificata, senza alterare il salvataggio. Scegli ora un cambio: sarà applicato prima della ripresa.'}</p></div>${halftimeIntro(ui.language)}${sim04TacticsPanel(w,ui,true)}${renderCareerTacticsPanel(w,ui.language,{halftime:true,compareId:ui.sim02CompareId})}<div class="modal-footer"><button type="button" class="btn btn-outline" data-action="close-modal">${ui.language==='en'?'Cancel matchday':'Annulla giornata'}</button><button type="button" class="btn btn-primary" data-action="sim04-half-continue">${ui.language==='en'?'Play second half':'Gioca il secondo tempo'}</button></div>`;
 }
 else if(m.type==='slot'){title=ui.language==='en'?'Select player':'Seleziona calciatore';inner=pickerModal(w,ui);}
 else if(m.type==='preview-discard-confirm'){title=ui.language==='en'?'Discard saved preview?':'Eliminare l’anteprima salvata?';inner=`<p>${ui.language==='en'?'The saved match commentary and playback position will be deleted. Your actual career and match results will not change.':'La cronaca della partita e il punto di riproduzione salvato verranno eliminati. La carriera ufficiale e i risultati non cambieranno.'}</p><div class="modal-footer"><button class="btn btn-quiet" type="button" data-action="close-modal">${ui.language==='en'?'Cancel':'Annulla'}</button><button class="btn btn-danger" type="button" data-action="preview-discard-confirm">${ui.language==='en'?'Discard preview':'Elimina anteprima'}</button></div>`;}
 return dialogFrame({type:m.type,title,body:inner,wide,lang:ui.language,closeIcon:icon('close',19)});
}
export function careerHub(w,ui){
  const en=ui.language==='en';
  const tr=(it,english)=>en?english:it;
  const overview=ui.careers||{activeSlotId:null,slots:[]};
  const date=s=>new Date(s).toLocaleString(en?'en-GB':'it-IT',{dateStyle:'medium',timeStyle:'short'});
  const records=overview.slots.map(slot=>{
    const active=slot.id===overview.activeSlotId;
    const healthy=slot.status==='ok';
    const country=LEAGUES.find(l=>l.id===slot.countryId);
    const countryName=country?.country?.[en?'en':'it']||slot.countryId;
    const competition=country?.competition||'';
    const moreOpen=ui.careerMoreId===slot.id;
    const vaultAvailable=ui.vaultIds?.includes(slot.id);
    const primaryAction=active
      ? `<button class="btn btn-outline" data-action="career-continue" data-id="${esc(slot.id)}">${tr('Continua','Continue')}</button>`
      : `<button class="btn btn-outline" data-action="career-load" data-id="${esc(slot.id)}">${tr('Apri','Open')}</button>`;
    const healthyActions=healthy?`${primaryAction}<button class="btn btn-quiet" data-action="career-export" data-id="${esc(slot.id)}">${icon('download',15)} ${tr('Esporta','Export')}</button><button class="btn btn-danger" data-action="career-delete" data-id="${esc(slot.id)}">${tr('Elimina','Delete')}</button><button class="btn btn-quiet" data-action="career-more" data-id="${esc(slot.id)}" aria-expanded="${moreOpen}" aria-controls="career-more-${esc(slot.id)}">${tr('Altre azioni','More')}</button>`:vaultAvailable?`<button class="btn btn-outline" data-action="career-vault-preview" data-id="${esc(slot.id)}">${tr('Recupera copia','Recover copy')}</button>`:'';
    const morePanel=healthy?`<div id="career-more-${esc(slot.id)}" class="career-more-panel" ${moreOpen?'':'hidden'} role="group" aria-label="${tr('Altre azioni','More actions')}"><button class="btn btn-quiet" data-action="career-rename" data-id="${esc(slot.id)}">${tr('Rinomina','Rename')}</button><button class="btn btn-quiet" data-action="career-duplicate" data-id="${esc(slot.id)}">${tr('Duplica','Duplicate')}</button><button class="btn btn-quiet" data-action="career-import-backups" data-id="${esc(slot.id)}">${tr('Backup','Backups')}</button><button class="btn btn-quiet" data-action="career-checkpoints" data-id="${esc(slot.id)}">${tr('Checkpoint','Checkpoints')}</button>${vaultAvailable?`<button class="btn btn-quiet" data-action="career-vault-preview" data-id="${esc(slot.id)}">${tr('Recupera copia','Recover copy')}</button>`:''}</div>`:'';
    return `<article class="career-card card-shell ${active?'career-active':''}" aria-label="${esc(slot.name)}">
       <div class="career-card-top"><div><span class="overline">${esc((country?.flag||'')+' '+countryName+(competition?' · '+competition:''))}</span><h2>${esc(slot.name)}</h2></div><span class="tag status-chip ${active?'tag-green':'tag-muted'}">${!healthy?tr('Da verificare','Needs attention'):active?tr('Attiva','Active'):tr('Disponibile','Available')}</span></div>
       <div class="career-meta"><span>${tr('Club','Club')}: <b>${esc(slot.clubName||tr('Da scegliere','Not selected'))}</b></span><span>${tr('Allenatore','Manager')}: <b>${esc(slot.manager)}</b></span><span>${tr('Stagione','Season')}: <b>${slot.season}</b></span><span>${tr('Data di gioco','Game date')}: <b>${slot.currentDate?esc(formatCareerDate(slot.currentDate,ui.language)):'—'}</b></span><span>${tr('Ultimo salvataggio','Last saved')}: <b>${esc(date(slot.lastSavedAt))}</b></span></div>
       ${!healthy?`<p class="career-warning" role="status">${tr('Questo slot richiede verifica. Le azioni non sicure sono disabilitate.','This slot needs attention. Unsafe actions are unavailable.')}</p>`:''}
       <div class="career-actions">${healthyActions}</div>
       ${morePanel}
      </article>`;
  }).join('');
  const m=ui.modal;
  const ck=m?.type==='career-checkpoints';
  const confirmRestore=m?.type==='career-checkpoint-confirm';
  const isRename=m?.type==='career-rename';
  const isDelete=m?.type==='career-delete';
  const vaultConfirm=m?.type==='career-vault-confirm';
  const active=overview.activeSlotId===m?.id;
  const kindText={"before-match":tr('Prima della partita','Before match'),"before-transfer":tr('Prima del trasferimento','Before transfer'),"before-season":tr('Prima della stagione','Before season'),"before-restore":tr('Prima del ripristino','Before restore')};
  const caption=vaultConfirm?tr('Recupera da IndexedDB','Recover from IndexedDB'):ck?tr('Punti di ripristino','Restore points'):confirmRestore?tr('Conferma ripristino','Confirm restore'):isRename?tr('Rinomina carriera','Rename career'):tr('Elimina carriera','Delete career');
  const dialog=m?.type?.startsWith('career-')&&!['career-import-preview','career-import-backups','career-import-backup-confirm'].includes(m.type)?`<div class="modal-layer" role="presentation" data-action="dismiss-modal"><div class="modal career-dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1" data-dialog-kind="${m.type}" data-stop-close>
    <header class="modal-header"><h2 id="dialog-title">${caption}</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="${tr('Chiudi','Close')}">${icon('close',19)}</button></header>
    <div class="modal-body">${ck?`
      <p class="muted small">${tr('Vengono conservati fino a 3 checkpoint per carriera (10 in totale) finché lo spazio locale lo consente.','Up to 3 checkpoints per career (10 in total) are retained while local storage allows.')}</p>
      ${ui.checkpointError?`<p class="career-warning" role="alert">${esc(ui.checkpointError)}</p>`:''}
      ${!active?`<p class="career-warning" role="status">${tr('Carica questa carriera per ripristinare un checkpoint.','Load this career before restoring a checkpoint.')}</p>`:''}
      <div class="career-checkpoint-list">${(ui.checkpoints||[]).length?(ui.checkpoints||[]).map(cp=>`<div class="career-checkpoint-row"><div><strong>${kindText[cp.kind]||esc(cp.kind)}</strong><small>${esc(date(cp.createdAt))} · ${tr('Stagione','Season')} ${cp.season}, ${tr('giornata','round')} ${cp.round}</small>${cp.status!=='ok'?`<small role="status">${tr('Non disponibile','Unavailable')}</small>`:''}</div><button class="btn btn-quiet" data-action="career-checkpoint-restore" data-id="${esc(m.id)}" data-value="${esc(cp.key)}" ${!active||cp.status!=='ok'?'disabled':''}>${tr('Ripristina','Restore')}</button></div>`).join(''):`<p class="muted">${tr('Nessun checkpoint disponibile per questa carriera.','No checkpoints available for this career.')}</p>`}</div>`:
      vaultConfirm?`<p>${tr('Ripristinare lo slot dalla copia IndexedDB verificata? Se esistono dati diversi, saranno prima conservati in un backup.','Restore this slot from the verified IndexedDB copy? Any different existing bytes will be backed up first.')}</p><p><strong>${esc(m.name)}</strong></p>`:
      confirmRestore?`<p>${tr('Ripristinare la carriera a questo checkpoint? I progressi successivi verranno sostituiti.','Restore this checkpoint? Later progress in this career will be replaced.')}</p><p><strong>${esc(m.name)}</strong></p><p class="muted">${tr('Una copia verificata dello stato attuale verrà salvata prima di procedere.','A verified copy of the current state will be saved before continuing.')}</p>`:
      isRename?`<label class="input-label" for="career-name">${tr('Nome della carriera','Career name')}</label>${clearableField({id:'career-name',label:tr('Nome della carriera','Career name'),value:m.name,maxLength:160,helpId:'career-name-hint'})}<p id="career-name-hint" class="field-help">${tr('Massimo 160 caratteri.','Maximum 160 characters.')}</p><p id="career-name-error" class="field-error" role="alert" hidden>${tr('Inserisci un nome per la carriera.','Enter a name for this career.')}</p>`:
      `<p>${tr('Vuoi eliminare definitivamente questo slot?','Delete this slot permanently?')}</p><p><strong>${esc(m.name)}</strong></p><p class="muted">${tr('Prima della cancellazione viene conservato un backup locale verificato.','A verified local backup is retained before deletion.')}</p>`}</div>
    <div class="modal-footer career-dialog-actions"><button class="btn btn-quiet" data-action="close-modal">${ck?tr('Chiudi','Close'):tr('Annulla','Cancel')}</button>${ck?'':`<button class="btn ${isRename?'btn-primary':isDelete?'btn-danger':'btn-primary'}" data-action="${isRename?'career-rename-confirm':isDelete?'career-delete-confirm':vaultConfirm?'career-vault-confirm':'career-checkpoint-confirm'}" data-id="${esc(m.id)}" ${confirmRestore?`data-value="${esc(m.key)}"`:''}>${isRename?tr('Salva nome','Save name'):isDelete?tr('Elimina carriera','Delete career'):vaultConfirm?tr('Recupera copia','Recover copy'):tr('Ripristina checkpoint','Restore checkpoint')}</button>`}</div>
  </div></div>`:'';
  const importPreview=ui.importPreview;
  const importDialog=m?.type==='career-import-preview'&&importPreview?`<div class="modal-layer" role="presentation" data-action="dismiss-modal"><div class="modal career-dialog career-import-dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1" data-dialog-kind="${m.type}" data-stop-close>
    <header class="modal-header"><h2 id="dialog-title">${tr('Anteprima importazione','Import preview')}</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="${tr('Chiudi','Close')}">${icon('close',19)}</button></header>
    <div class="modal-body"><p class="muted small">${tr('Nessuna carriera verrà modificata prima della conferma. Controlla i dati importati.','No career will be changed until you confirm. Review the incoming data.')}</p>
      <p><strong>${importPreview.entries.length} ${tr('carriere da importare','careers to import')}</strong> · ${importPreview.kind==='bundle'?tr('Archivio completo JSON','Full JSON archive'):tr('Salvataggio JSON singolo','Single JSON save')}</p>
      <div class="career-import-list">${importPreview.entries.map(e=>{const team=e.career.teams.find(t=>t.id===e.career.clubId);return `<div class="career-import-row"><strong>${esc(e.name)}</strong><small>${esc(team?.name||tr('Club da scegliere','Club not selected'))} · ${esc(e.career.countryId||'IT')} · ${tr('Stagione','Season')} ${e.career.season} / ${tr('Giornata','Round')} ${e.career.round} · v${e.career.version}</small></div>`;}).join('')}</div>
      <label class="input-label" for="career-import-mode">${tr('Modalità di importazione','Import mode')}</label>${selectControl({id:'career-import-mode',className:'select-block',value:ui.importMode,options:[{value:'add',label:tr('Aggiungi nuove carriere (conserva tutte le esistenti)','Add new careers (keep existing saves)')},{value:'replace',label:importPreview.kind==='bundle'?tr('Sostituisci gli slot con gli stessi identificativi','Replace slots with matching IDs'):tr('Sostituisci una carriera esistente','Replace an existing career')}]})}
      ${ui.importMode==='replace'&&importPreview.kind==='single'?`<label class="input-label" for="career-import-target">${tr('Carriera da sostituire','Career to replace')}</label>${selectControl({id:'career-import-target',className:'select-block',value:ui.importTarget,options:[{value:'',label:tr('Seleziona una carriera','Choose a career')},...overview.slots.filter(slot=>slot.status==='ok').map(slot=>({value:slot.id,label:slot.name}))]})}`:''}
      ${ui.importMode==='replace'?`<p class="career-warning">${tr('Le carriere di destinazione verranno sostituite. Verrà creata una copia di sicurezza verificata di ciascuna prima di modificare i dati.','Destination careers will be replaced. A verified recovery copy will be made for each before writing.')}</p>`:''}
      ${ui.importError?`<p class="career-warning" role="alert">${esc(ui.importError)}</p>`:''}</div>
    <div class="modal-footer career-dialog-actions"><button class="btn btn-quiet" data-action="close-modal">${tr('Annulla','Cancel')}</button><button class="btn btn-primary" data-action="career-import-confirm">${tr('Conferma importazione','Confirm import')}</button></div></div></div>`:'';
  const backupDialog=['career-import-backups','career-import-backup-confirm'].includes(m?.type)?`<div class="modal-layer" role="presentation" data-action="dismiss-modal"><div class="modal career-dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1" data-dialog-kind="${m.type}" data-stop-close>
    <header class="modal-header"><h2 id="dialog-title">${tr('Backup della carriera','Career backups')}</h2><button class="icon-button" type="button" data-action="close-modal" aria-label="${tr('Chiudi','Close')}">${icon('close',19)}</button></header>
    <div class="modal-body">${m.type==='career-import-backups'?`<p class="muted small">${tr('Copie precedenti alle importazioni con sostituzione. I checkpoint sono gestiti separatamente.','Copies from before a replacement import. Checkpoints are managed separately.')}</p><div class="career-checkpoint-list">${(ui.importBackups||[]).map(b=>`<div class="career-checkpoint-row"><div><strong>${tr('Copia precedente','Previous copy')}</strong><small>${b.createdAt?esc(date(b.createdAt)):tr('Data sconosciuta','Unknown date')}</small><small>${b.status==='ok'?tr('Verificata','Verified'):tr('Da verificare','Needs attention')}</small></div><button class="btn btn-quiet" data-action="career-import-backup-select" data-id="${esc(m.id)}" data-value="${esc(b.key)}" ${b.status!=='ok'?'disabled':''}>${tr('Ripristina','Restore')}</button></div>`).join('')||`<p class="muted">${tr('Nessun backup di importazione per questa carriera.','No import backups for this career.')}</p>`}</div>`:
      `<p>${tr('Ripristinare la copia precedente? La carriera attuale verrà prima salvata come nuovo backup.','Restore this previous copy? Your current career will first be saved as a new backup.')}</p><p><strong>${esc(m.name||'')}</strong></p>`}</div>
    <div class="modal-footer career-dialog-actions"><button class="btn btn-quiet" data-action="close-modal">${tr('Chiudi','Close')}</button>${m.type==='career-import-backup-confirm'?`<button class="btn btn-primary" data-action="career-import-backup-confirm" data-id="${esc(m.id)}" data-value="${esc(m.key)}">${tr('Conferma ripristino','Confirm restore')}</button>`:''}</div></div></div>`:'';
  const securityNeedsAttention=Boolean(ui.storageWarning)||['warning','unavailable'].includes(ui.vaultState);
  const storageStatus=ui.vaultState==='ok'
    ?tr('Archivio principale IndexedDB attivo. Copia di recupero verificata.','IndexedDB primary storage active. Recovery copy verified.')
    :ui.vaultState==='unavailable'
      ?tr('Archivio principale IndexedDB attivo; copia secondaria non disponibile. Esporta un backup JSON.','IndexedDB primary is active; secondary recovery copy unavailable. Export a JSON backup.')
      :ui.vaultState==='warning'
        ?tr('Una copia secondaria richiede verifica. Archivio principale attivo.','Secondary recovery copy needs attention. Primary storage remains active.')
        :tr('Archivio principale IndexedDB attivo. Verifica delle copie secondarie in corso.','IndexedDB primary active. Checking secondary recovery copies.');
  const securitySummary=securityNeedsAttention
    ?tr('Sicurezza e recupero dati · Attenzione richiesta','Security and data recovery · Attention required')
    :ui.vaultState==='ok'
      ?tr('Archiviazione protetta','Storage protected')
      :tr('Sicurezza e recupero dati','Security and data recovery');
  const headActions=`<div class="career-head-actions"><button class="btn btn-primary" data-action="career-new">${icon('plus',17)} ${tr('Nuova carriera','New career')}</button><button class="btn btn-quiet" data-action="career-import">${icon('upload',17)} ${tr('Importa','Import')}</button></div>`;
  return `<div class="career-hub">${skipToContent(ui.language)}<header class="career-hub-top"><div class="brand"><span class="brand-icon">${icon('shield',23)}</span><span>FOOTBALL <b>ARCHITECT</b><small>MANAGER</small></span></div><div class="career-top-actions">${languagePicker(ui,'careers')}<button class="btn btn-quiet" data-action="career-back">${tr('Indietro','Back')}</button></div></header>
    <main id="main-content" tabindex="-1" class="career-hub-main">${sectionHead(tr('SALVATAGGI LOCALI','LOCAL SAVES'),tr('Le tue carriere','Your careers'),tr('Apri una carriera o creane una nuova. Gli strumenti di recupero restano disponibili quando servono.','Open a career or create a new one. Recovery tools remain available when needed.'),headActions)}
    <input type="file" id="career-import-file" accept=".json,application/json" hidden />
    ${ui.storageWarning?`<p class="career-warning career-storage-alert" role="alert">${esc(ui.storageWarning)}</p>`:''}
    <div class="career-grid">${records||`<div class="panel career-empty"><h2>${tr('Nessuna carriera salvata','No saved careers')}</h2><p>${tr('Crea la prima carriera per iniziare.','Create your first career to get started.')}</p></div>`}</div>
    <details class="career-security" ${securityNeedsAttention?'open':''}>
      <summary><span>${icon('shield',17)} ${securitySummary}</span><span class="career-security-chevron" aria-hidden="true">⌄</span></summary>
      <div class="career-security-body">
        <div class="feedback-inline ${ui.vaultState==='pending'?'feedback-inline-pending':''}" ${ui.vaultState==='pending'?'aria-busy="true"':''}><p class="career-note" role="status">${storageStatus}${ui.storageEstimate?.supported?` · ${tr('Spazio disponibile stimato','Estimated available space')}: ${Math.round(ui.storageEstimate.remaining/1e6)} MB`:''}</p>${ui.vaultState==='warning'||ui.vaultState==='unavailable'?`<button class="btn btn-quiet feedback-retry" data-action="retry-vault-sync">${tr('Riprova verifica','Retry check')}</button>`:''}</div>
        <div class="career-security-actions"><button class="btn btn-quiet" data-action="career-export-all">${icon('download',17)} ${tr('Esporta tutte','Export all')}</button><button class="btn btn-quiet" data-action="export-emergency">${icon('shield',17)} ${tr('Esporta emergenza','Emergency export')}</button><button class="btn btn-quiet" data-action="request-storage-persistence">${icon('shield',17)} ${tr('Proteggi archiviazione','Protect storage')}</button></div>
      </div>
    </details>
    </main>${dialog}${importDialog}${backupDialog}</div>`;
}

/** MGT01: save-derived read-only assessment and deliberate actions. */
export function careerBoardPanel(w,ui){
 const en=ui.language==='en',label=(it,enText)=>en?enText:it;
 if(!boardEnabled(w))return sectionHead('MGT01',label('Dirigenza','Board of directors'),label('Obiettivi, fiducia e carriera manageriale.','Objectives, confidence and management career.'))+'<section class="panel"><h2>'+label('Sistema da ripristinare','System needs repair')+'</h2><p role="alert">'+label('La dirigenza è parte integrante della carriera. Ricarica il salvataggio per eseguire la migrazione automatica.','The board is part of every career. Reload the save to run automatic migration.')+'</p></section>';
 const b=w.advancedV1.boardV1,goal=b.targets;
 const causes={appointment:["Nomina","Appointment"],win:["Vittoria","Win"],loss:["Sconfitta","Defeat"],draw:["Pareggio","Draw"],cautious:["Obiettivi prudenti","Cautious targets"],balanced:["Obiettivi equilibrati","Balanced targets"],ambitious:["Obiettivi ambiziosi","Ambitious targets"],annual_assessment:["Valutazione annuale","Annual assessment"],persistent_underperformance:["Risultati insufficienti","Underperformance"],low_confidence:["Fiducia insufficiente","Low confidence"],new_club:["Nuova panchina","New appointment"],new_season:["Nuova stagione","New season"],contract_extended:["Rinnovo","Contract extension"],contract_review:["Riesame contratto","Contract review"]};
 const txt=k=>causes[k]?.[en?1:0]??String(k).replaceAll('_',' ');
 const status=label(b.status==='active'?'In carica':b.status==='dismissed'?'Esonerato':'Carriera terminata',b.status==='active'?'In office':b.status==='dismissed'?'Dismissed':'Career ended');
 const review=b.history.at(-1);
 return `${sectionHead('MGT01',label('Dirigenza e obiettivi','Club board and objectives'),label('Valutazioni motivate dai risultati ufficiali.','Assessments based on official results.'))}
 <div class="kpi-grid metric-grid board-metrics"><div class="kpi metric-card"><div class="kpi-name">${label('FIDUCIA','CONFIDENCE')}</div><div class="kpi-main">${b.trust}<span class="kpi-suffix">/100</span></div></div><div class="kpi metric-card"><div class="kpi-name">${label('TIFOSI','SUPPORTERS')}</div><div class="kpi-main">${b.fans}<span class="kpi-suffix">/100</span></div></div><div class="kpi metric-card"><div class="kpi-name">${label('MEDIA','MEDIA')}</div><div class="kpi-main">${b.media}<span class="kpi-suffix">/100</span></div></div><div class="kpi metric-card"><div class="kpi-name">${label('CONTRATTO','CONTRACT')}</div><div class="kpi-main">${b.contractUntil}</div></div></div>
 <section class="panel"><h2>${label('Situazione allenatore','Manager status')} · ${esc(status)}</h2><p>${label('Ogni variazione deriva da partite, posizione e sostenibilità economica. Un esonero richiede avvertimenti precedenti.','Every change is driven by matches, league performance and finances. Dismissal requires prior warnings.')}</p>
 ${b.status==='dismissed'?`<h3>${label('Nuove panchine disponibili','Available managerial jobs')}</h3><div class="board-jobs">${boardJobs(w).map(c=>`<button class="btn btn-outline" data-action="board-accept-job" data-id="${c.id}">${esc(c.name)} (${c.reputation})</button>`).join('')}</div><button class="btn btn-quiet" data-action="board-retire">${label('Termina carriera','End manager career')}</button>`:''}
 ${b.status==='retired'?`<p>${label('Il salvataggio storico è conservato.','The historical save is preserved.')}</p>`:''}
 </section>
 <section class="panel"><h2>${label('Obiettivi stagionali','Season targets')}</h2><p>${label('Profilo','Strategy')}: <strong>${esc(txt(b.plan))}</strong> · ${label('Avvertimenti','Warnings')}: ${b.warnings}</p>
 <div class="board-goals"><p>${label('Classifica: raggiungere il','League finish: reach')} <strong>${localizedStanding(goal.leaguePosition,{lang:ui.language})}</strong> ${label('posto o migliore','place or better')}</p><p>${label('Coppa: turno','Cup: round')} ≥ ${goal.cupRound} (${label('se attiva','if enabled')})</p><p>${label('Presenze under 21','U21 appearances')}: ≥ ${goal.youthAppearances} (${label('con vivaio','if academy enabled')})</p><p>${label('Sostenibilità del saldo','Financial balance ratio')}: ≥ ${Math.round(goal.minBalanceRatio*100)}%</p><p>${label('Stile tattico','Tactical style')}: ${esc(goal.style)}</p></div>
 ${!b.negotiated&&w.round===0&&b.status==='active'?`<p>${label('Negozia una sola volta, prima della prima partita.','Negotiate once, before the first match.')}</p><div class="board-jobs">${[['cautious',label('Prudenti','Cautious')],['balanced',label('Equilibrati','Balanced')],['ambitious',label('Ambiziosi','Ambitious')]].map(([p,t])=>`<button class="btn btn-outline" data-action="board-negotiate" data-plan="${p}">${t}</button>`).join('')}</div>`:''}</section>
 <section class="panel"><h2>${label('Storico delle valutazioni','Assessment history')}</h2>${review?`<p>${label('Ultima stagione','Last season')} ${review.season}: ${review.satisfied}/${review.total} ${label('obiettivi verificabili raggiunti','assessable objectives met')}; ${label('classifica','finish')} ${review.finish}.</p>`:`<p>${label('La prima valutazione annuale arriverà a fine stagione.','The first annual review will be issued at season end.')}</p>`}
 <div class="board-events" role="list">${b.events.slice(-15).reverse().map(e=>`<div class="board-event" role="listitem"><strong>${label('Stagione','Season')} ${e.season} · ${label('Giornata','Matchday')} ${e.round}</strong><span>${esc(txt(e.cause))}</span><span>${e.delta>0?'+':''}${e.delta} · ${label('fiducia','confidence')} ${e.trust}/100</span></div>`).join('')}</div></section>`;
}
/** WRD06: identity and contract history are independent of the coached club. */
export function careerManagerPanel(w,ui){
 const en=ui.language==='en',tr=(it,english)=>en?english:it;
 if(!boardEnabled(w))return sectionHead('WRD06',tr('Carriera allenatore','Manager career'),tr('Sistema ufficiale non inizializzato: ricarica la carriera per la migrazione automatica.','Official system not initialized: reload the career to run automatic migration.'));
 if(!managerCareerEnabled(w))return sectionHead('WRD06',tr('Carriera allenatore','Manager career'),tr('Sistema da ripristinare: ricarica la carriera per completare la migrazione automatica.','System needs repair: reload the career to complete automatic migration.'));
 const s=w.advancedV1.managerV1,p=s.profile;const vac=managerVacancies(w);
 const vacancies=vac.filter(c=>c.countryId===w.countryId).slice(0,10);
 const abroad=vac.filter(c=>c.countryId!==w.countryId).slice(0,8);
 const open=s.offers.filter(o=>o.status==='open');
 return `${sectionHead('WRD06',tr('Carriera allenatore','Manager career'),tr('Profilo, incarichi, offerte e riconoscimenti.','Profile, appointments, offers and honours.'))}
 <div class="kpi-grid metric-grid"><div class="kpi metric-card"><div class="kpi-name">${tr('REPUTAZIONE','REPUTATION')}</div><div class="kpi-main">${p.reputation}<span class="kpi-suffix">/100</span></div></div><div class="kpi metric-card"><div class="kpi-name">${tr('ESPERIENZA','EXPERIENCE')}</div><div class="kpi-main">${p.experience}</div></div><div class="kpi metric-card"><div class="kpi-name">${tr('INCARICHI','JOBS')}</div><div class="kpi-main">${s.jobs.length}</div></div><div class="kpi metric-card"><div class="kpi-name">${tr('TROFEI','HONOURS')}</div><div class="kpi-main">${s.awards.length}</div></div></div>
 <section class="panel"><h2>${esc(p.name)}</h2><p>${tr('Origine','Origin')}: ${esc(p.origin||'—')} · ${tr('Stile','Style')}: ${esc(p.style)} · ${tr('Stato','Status')}: ${esc(s.status)}</p><p>${tr('Paese attuale','Current country')}: ${esc(w.countryId)} · ${tr('Contratto fino alla stagione','Contract through season')}: ${s.jobs.at(-1)?.contractUntil}</p></section>
 <section class="panel"><h2>${tr('Offerte e colloqui','Offers and interviews')}</h2>${open.length?open.map(o=>`<div class="board-event"><strong>${esc(o.clubName)}</strong><span>${o.salaryEUR.toLocaleString(en?'en-GB':'it-IT')} € / ${tr('anno','year')} · ${o.contractYears} ${tr('anni','years')}</span><div class="board-jobs"><button class="btn btn-outline" data-action="manager-counter" data-id="${o.id}">${tr('Controproposta +10%','Counter +10%')}</button><button class="btn btn-primary" data-action="manager-offer-accept" data-id="${o.id}">${tr('Accetta','Accept')}</button><button class="btn btn-quiet" data-action="manager-offer-decline" data-id="${o.id}">${tr('Rifiuta','Decline')}</button></div></div>`).join(''):`<p>${tr('Nessuna offerta in corso.','No active offers.')}</p>`}</section>
 <section class="panel"><h2>${tr('Panchine disponibili','Manager vacancies')}</h2><div class="board-jobs">${vacancies.map(c=>`<button class="btn btn-outline" data-action="manager-apply" data-value="${esc(c.clubKey)}">${esc(c.name)} · ${c.reputation}</button>`).join('')||`<p>${tr('Nessuna posizione aperta.','No current vacancies.')}</p>`}</div><h3>${tr('Opportunità internazionali','International vacancies')}</h3><p class="muted">${tr('Puoi candidarti all’estero soltanto prima della prima giornata stagionale. Una carriera avviata deve prima raggiungere la stagione successiva.','You may apply abroad only before the first matchday of a season. Otherwise, finish the season first.')}</p><div class="board-jobs">${abroad.map(c=>c.supported?`<button class="btn btn-outline" data-action="manager-apply" data-value="${esc(c.clubKey)}">${esc(c.countryId)} · ${esc(c.name)}</button>`:`<span>${esc(c.countryId)} · ${esc(c.name)}</span>`).join('')||'—'}</div></section>
 <section class="panel"><h2>${tr('Cronologia incarichi e palmarès','Job history and honours')}</h2><div class="board-events">${s.jobs.slice().reverse().map(j=>`<div class="board-event"><strong>${esc(j.clubName)} (${esc(j.countryId)})</strong><span>${tr('Stagione','Season')} ${j.startSeason} · ${tr('Giornata','Round')} ${j.startRound} → ${j.endSeason??tr('In corso','Current')}</span><span>${j.salaryEUR.toLocaleString(en?'en-GB':'it-IT')} € / ${tr('anno','year')}</span></div>`).join('')}</div><div class="board-events">${s.awards.slice(-20).reverse().map(a=>`<div class="board-event"><strong>${a.season}</strong><span>${esc(a.type)}</span></div>`).join('')||`<p>${tr('Nessun titolo ancora.','No honours yet.')}</p>`}</div></section>`;
}
function notFoundPage(ui){
 const en=ui.language==='en',path=esc(ui.routeNotFoundPath||'/');
 return `<div class="fa-menu-page"><main class="fa-menu-main" id="main-content" tabindex="-1"><div class="fa-menu-intro"><span class="overline">404</span><h1>${en?'Page not found':'Pagina non trovata'}</h1></div><section class="fa-menu-panel"><div class="fa-menu-actions"><button class="btn btn-primary" data-action="menu-home">${en?'Main menu':'Menu principale'}</button><button class="btn btn-outline" data-action="open-careers">${en?'Careers':'Carriere'}</button></div></section></main></div>`;
}
export function view(w,ui){if(ui.page==='not-found')return notFoundPage(ui);if(ui.page==='home'||ui.page==='home-settings')return renderHomeMenu(w,ui,{languagePicker:languagePicker(ui,'home')});if(ui.page==='careers')return careerHub(w,ui);if(ui.page==='new-career'||!w.clubId)return onboarding(w,ui);let body;switch(ui.page){case 'club':body=clubPage(w,ui);break;case 'squad':body=squad(w,ui);break;case 'tactics':body=tactics(w,ui);break;case 'calendar':body=calendar(w,ui);break;case 'league':body=league(w,ui);break;case 'market':body=market(w,ui);break;case 'world':body=careerWorldPanel(w,ui);break;case 'training':body=training(w,ui);break;case 'youth':body=`${sectionHead('VIVAIO',ui.language==='en'?'Youth Academy':'Accademia',ui.language==='en'?'Develop your future first team.':'Prepara la prossima generazione.')}${careerYouthPanel(w,ui.language)}`;break;case 'finance':body=finance(w,ui);break;case 'board':body=careerBoardPanel(w,ui);break;case 'manager':body=careerManagerPanel(w,ui);break;case 'inbox':body=inbox(w,ui);break;case 'settings':body=settings(w,ui);break;case 'advanced':body=advancedPage(w,ui);break;case 'match-preview':body=matchPreviewPage(w,ui.matchPreview,ui.language);break;default:body=dashboard(w,ui);}return shell(w,ui,body);}
